/** Display-only formatting helpers for the renderer. */

const timeFormat = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
const dateFormat = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' });
const dateYearFormat = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
const fullFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'full', timeStyle: 'medium' });

function startOfDay(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
}

/** Short, readable timestamp: "Today, 14:32", "Yesterday, 09:05", "Mar 3, 10:00", "Mar 3, 2025, 10:00". */
export function formatTimestamp(iso: string, now: Date = new Date()): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'Unknown time';

  const time = timeFormat.format(date);
  const dayDiff = Math.round((startOfDay(now) - startOfDay(date)) / 86_400_000);
  if (dayDiff === 0) return `Today, ${time}`;
  if (dayDiff === 1) return `Yesterday, ${time}`;
  if (date.getFullYear() === now.getFullYear()) return `${dateFormat.format(date)}, ${time}`;
  return `${dateYearFormat.format(date)}, ${time}`;
}

/** Full timestamp for tooltips. */
export function formatFullTimestamp(iso: string): string {
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? 'Unknown time' : fullFormat.format(date);
}

/** Strip Electron's IPC wrapper from an error so the user sees the real reason. */
export function formatIpcError(err: unknown): string {
  const raw = err instanceof Error ? err.message : String(err);
  return raw.replace(/^Error invoking remote method '[^']+':\s*(Error:\s*)?/, '') || 'Unknown error';
}

