 28	export const smallButton: CSSProperties = {
 29	  padding: '3px 10px',
 30	  background: 'transparent',
 31	  color: '#c0c0e0',
 32	  border: '1px solid #2a3a6e',
 33	  borderRadius: '4px',
 34	  cursor: 'pointer',
 35	  fontSize: '12px',
 36	};
 37	
 38	interface Props {
 39	  exchange: ConversationExchange;
 40	  /** The exchange this one follows up on, when it is still in the history. */
 41	  parent: ConversationExchange | null;
 42	  highlighted: boolean;
 43	  isDocumentAvailable: (documentId: string) => boolean;
 44	  onOpenDocument: (documentId: string) => void;
 45	  onFollowUp: (exchange: ConversationExchange) => void;
 46	  onJumpTo: (exchangeId: string) => void;
 47	}
 48	
 49	export function ExchangeItem({
 50	  exchange,
 51	  parent,
 52	  highlighted,
 53	  isDocumentAvailable,
 54	  onOpenDocument,
 55	  onFollowUp,
 56	  onJumpTo,
 57	}: Props) {
 58	  const { response } = exchange;
 59	  const isLong = response.answer.length > LONG_ANSWER_CHARS;
 60	  const [expanded, setExpanded] = useState(false);
 61	  const [showSources, setShowSources] = useState(true);
 62	  const [copyStatus, setCopyStatus] = useState('');
 63	  const copyTimer = useRef<number | undefined>(undefined);
 64	  const answerId = `answer-${exchange.id}`;
 65	  const sourcesId = `sources-${exchange.id}`;
 66	  const confidencePct = Math.round(response.confidence * 100);
 67	  const lowConfidence = response.confidence < 0.5;
 68	
 69	  useEffect(() => () => window.clearTimeout(copyTimer.current), []);
 70	
 71	  const copyAnswer = async () => {
 72	    try {
 73	      await navigator.clipboard.writeText(response.answer);
 74	      setCopyStatus('Copied');
 75	    } catch {
 76	      setCopyStatus('Copy failed');
 77	    }
 78	    window.clearTimeout(copyTimer.current);
 79	    copyTimer.current = window.setTimeout(() => setCopyStatus(''), 2000);
 80	  };
 81	
 82	  return (
 83	    <article
 84	      id={`exchange-${exchange.id}`}
 85	      tabIndex={-1}
 86	      aria-labelledby={`question-${exchange.id}`}
 87	      style={{
 88	        display: 'flex',
 89	        flexDirection: 'column',
 90	        gap: '8px',
 91	        padding: '8px',
 92	        borderRadius: '8px',
 93	        outlineOffset: '2px',
 94	        background: highlighted ? 'rgba(83, 52, 131, 0.18)' : 'transparent',
 95	        transition: 'background 0.3s',
 96	      }}
 97	    >
 98	      {/* User question */}
 99	      <div style={{ alignSelf: 'flex-end', display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '4px', maxWidth: '80%' }}>
100	        <div style={metaText}>
101	          <span style={{ fontWeight: 600, color: '#c9b6ef' }}>You</span>
102	          {' · '}
103	          <time dateTime={exchange.askedAt} title={formatFullTimestamp(exchange.askedAt)}>
104	            {formatTimestamp(exchange.askedAt)}
105	          </time>
106	        </div>
107	        {exchange.followUpOf && (
108	          <div style={metaText}>
109	            {parent ? (
110	              <button
111	                type="button"
112	                onClick={() => onJumpTo(parent.id)}
113	                style={{ ...smallButton, border: 'none', padding: 0, color: '#9a9ac0', textDecoration: 'underline' }}
114	                title="Jump to the earlier question"
115	              >
116	                ↪ Follow-up to “{truncate(parent.question, 60)}”
117	              </button>
118	            ) : (
119	              <span>↪ Follow-up to an earlier question</span>
120	            )}
121	          </div>
122	        )}
123	        <h3 id={`question-${exchange.id}`} style={{ ...userBubble, maxWidth: '100%', fontWeight: 400, margin: 0 }}>
124	          {exchange.question}
125	        </h3>
126	      </div>
127	
128	      {/* Assistant answer */}
129	      <div style={{ alignSelf: 'flex-start', maxWidth: '88%', display: 'flex', flexDirection: 'column', gap: '4px' }}>
130	        <div style={metaText}>
131	          <span style={{ fontWeight: 600, color: '#8fb3ff' }}>Assistant</span>
132	          {' · '}
133	          <time dateTime={response.timestamp} title={formatFullTimestamp(response.timestamp)}>
134	            {formatTimestamp(response.timestamp)}
135	          </time>
136	          {' · '}
137	          <span
138	            style={{ color: lowConfidence ? '#f0ad4e' : '#5cb85c' }}
139	            title="How well the answer is supported by your indexed documents"
140	          >
141	            {lowConfidence ? 'Low confidence' : 'Confidence'} {confidencePct}%
142	          </span>
143	        </div>
144	        <div
145	          style={{
146	            ...bubbleBase,
147	            background: '#1a1a3e',
148	            border: '1px solid #0f3460',
149	            borderBottomLeftRadius: '2px',
150	          }}
151	        >
152	          <div id={answerId}>
153	            {isLong && !expanded ? `${response.answer.slice(0, LONG_ANSWER_CHARS).trimEnd()}…` : response.answer}
154	          </div>
155	          {isLong && (
156	            <button
157	              type="button"
158	              aria-expanded={expanded}
159	              aria-controls={answerId}
160	              onClick={() => setExpanded(!expanded)}
161	              style={{ ...smallButton, marginTop: '8px' }}
162	            >
163	              {expanded ? 'Show less' : `Show full answer (${response.answer.length.toLocaleString()} characters)`}
164	            </button>
165	          )}
166	
167	          {response.citations.length > 0 ? (
168	            <div style={{ marginTop: '12px', borderTop: '1px solid #0f3460', paddingTop: '8px', whiteSpace: 'normal' }}>
169	              <button
170	                type="button"
171	                aria-expanded={showSources}
172	                aria-controls={sourcesId}
173	                onClick={() => setShowSources(!showSources)}
174	                style={{ ...smallButton, border: 'none', padding: 0, fontWeight: 600, color: '#8888bb' }}
175	              >
176	                {showSources ? '▾' : '▸'} Sources ({response.citations.length})
177	              </button>
178	              {showSources && (
179	                <ol id={sourcesId} style={{ listStyle: 'none', margin: '6px 0 0', padding: 0, display: 'flex', flexDirection: 'column', gap: '6px' }}>
180	                  {response.citations.map((citation, i) => (
181	                    <CitationItem
182	                      key={`${citation.documentId}-${citation.chunkIndex}-${i}`}
183	                      number={i + 1}
184	                      citation={citation}
185	                      available={isDocumentAvailable(citation.documentId)}
186	                      onOpen={() => onOpenDocument(citation.documentId)}
187	                    />
188	                  ))}
189	                </ol>
190	              )}
191	            </div>
192	          ) : (
193	            <p style={{ marginTop: '10px', fontSize: '12px', fontStyle: 'italic', color: '#9a9ac0', whiteSpace: 'normal' }}>
194	              No sources cited — no indexed document matched this question, so the answer is not grounded in your documents.
195	            </p>
196	          )}
197	        </div>
198	
199	        <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
200	          <button type="button" onClick={copyAnswer} style={smallButton} aria-label={`Copy answer to “${truncate(exchange.question, 60)}”`}>
201	            Copy answer
202	          </button>
203	          <button type="button" onClick={() => onFollowUp(exchange)} style={smallButton} aria-label={`Ask a follow-up to “${truncate(exchange.question, 60)}”`}>
204	            Follow up
205	          </button>
206	          <span role="status" style={metaText}>{copyStatus}</span>
207	        </div>
208	      </div>
209	    </article>
210	  );
211	}
212	
213	function CitationItem({
214	  number,
215	  citation,
216	  available,
217	  onOpen,
218	}: {
219	  number: number;
220	  citation: Citation;
221	  available: boolean;
222	  onOpen: () => void;
223	}) {
224	  const label = `${citation.documentTitle} · chunk ${citation.chunkIndex}`;
225	  return (
226	    <li style={{ paddingLeft: '8px', borderLeft: '2px solid #533483', fontSize: '12px' }}>
227	      <div style={{ display: 'flex', gap: '6px', alignItems: 'baseline', flexWrap: 'wrap' }}>
228	        <span style={{ color: '#8888bb' }}>[{number}]</span>
229	        {available ? (
230	          <button
231	            type="button"
232	            onClick={onOpen}
233	            title="Open this document"
234	            style={{ ...smallButton, border: 'none', padding: 0, color: '#8fb3ff', textDecoration: 'underline' }}
235	          >
236	            {label}
237	          </button>
238	        ) : (
239	          <span style={{ color: '#8888bb' }}>
240	            {label} <em>(document no longer available)</em>
241	          </span>
242	        )}
243	      </div>
244	      <blockquote style={{ margin: '4px 0 0', color: '#b0b0d0', whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>
245	        {citation.excerpt}
246	      </blockquote>
247	    </li>
248	  );
249	}
250	
251	function truncate(text: string, max: number): string {
252	  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
253	}
  1	import { ConversationExchange } from '../../shared/types';
