  9	
 10	/** Sidebar index of past questions; selecting one jumps to it in the conversation. */
 11	export function ConversationHistory({ conversation, selectedId, onSelect }: Props) {
 12	  if (conversation.length === 0) {
 13	    return (
 14	      <div style={{ padding: '20px', color: '#888', textAlign: 'center', fontSize: '13px' }}>
 15	        No conversation history yet. Ask a question to get started.
 16	      </div>
 17	    );
 18	  }
 19	
 20	  return (
 21	    <nav aria-label="Past questions" style={{ flex: 1, overflow: 'auto' }}>
 22	      <ol style={{ listStyle: 'none', margin: 0, padding: 0 }}>
 23	        {conversation.map((exchange, i) => {
 24	          const selected = exchange.id === selectedId;
 25	          const citationCount = exchange.response.citations.length;
 26	          return (
 27	            <li key={exchange.id}>
 28	              <button
 29	                type="button"
 30	                onClick={() => onSelect(exchange.id)}
 31	                aria-current={selected ? 'true' : undefined}
 32	                title={exchange.question}
 33	                style={{
 34	                  display: 'block',
 35	                  width: '100%',
 36	                  textAlign: 'left',
 37	                  padding: '10px 16px',
 38	                  background: selected ? '#0f3460' : 'transparent',
 39	                  color: '#e0e0e0',
 40	                  border: 'none',
 41	                  borderBottom: '1px solid #0f3460',
 42	                  cursor: 'pointer',
 43	                  font: 'inherit',
 44	                }}
 45	              >
 46	                <div style={{ fontSize: '13px', fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
 47	                  <span style={{ color: '#888' }}>{i + 1}. </span>
 48	                  {exchange.question}
 49	                </div>
 50	                <div style={{ fontSize: '11px', color: '#9a9ac0', marginTop: '2px' }}>
 51	                  <time dateTime={exchange.askedAt} title={formatFullTimestamp(exchange.askedAt)}>
 52	                    {formatTimestamp(exchange.askedAt)}
 53	                  </time>
 54	                  {' · '}
 55	                  {citationCount === 0 ? 'no sources' : `${citationCount} ${citationCount === 1 ? 'source' : 'sources'}`}
 56	                  {exchange.followUpOf && ' · follow-up'}
 57	                </div>
 58	              </button>
 59	            </li>
 60	          );
 61	        })}
 62	      </ol>
 63	    </nav>
 64	  );
 65	}
