  1	import { useState, useCallback, useEffect, useMemo } from 'react';
  2	import { DocumentList } from './components/DocumentList';
  3	import { QuestionPanel, PendingQuestion, FailedQuestion, ExchangeSelection } from './components/QuestionPanel';
  4	import { DocumentDetail } from './components/DocumentDetail';
  5	import { ConversationHistory } from './components/ConversationHistory';
  6	import { StatusBar } from './components/StatusBar';
  7	import { Document, AppStatus, ConversationExchange } from '../shared/types';
  8	import { formatIpcError } from './format';
  9	
 10	const tabStyle = (active: boolean) => ({
 11	  flex: 1,
 12	  padding: '8px',
 13	  background: active ? '#0f3460' : 'transparent',
 14	  color: active ? '#e0e0e0' : '#9a9ac0',
 15	  border: 'none',
 16	  borderBottom: active ? '2px solid #533483' : '2px solid transparent',
 17	  cursor: 'pointer',
 18	  fontSize: '12px',
 19	  fontWeight: 500,
 20	});
 21	
 22	export function App() {
 23	  const [documents, setDocuments] = useState<Document[]>([]);
 24	  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
 25	  const [appStatus, setAppStatus] = useState<AppStatus>({
 26	    documentsLoaded: 0,
 27	    indexStatus: 'idle',
 28	    lastActivity: '',
 29	  });
 30	  const [conversation, setConversation] = useState<ConversationExchange[]>([]);
 31	  const [historyError, setHistoryError] = useState<string | null>(null);
 32	  const [pending, setPending] = useState<PendingQuestion | null>(null);
 33	  const [failed, setFailed] = useState<FailedQuestion | null>(null);
 34	  const [selection, setSelection] = useState<ExchangeSelection | null>(null);
 35	  const [activeTab, setActiveTab] = useState<'documents' | 'conversation'>('documents');
 36	
 37	  const refreshDocuments = useCallback(async () => {
 38	    try {
 39	      const docs = await window.knowledgeBase.documents.list();
 40	      setDocuments(docs);
 41	      const status = await window.knowledgeBase.indexing.status();
 42	      setAppStatus(status);
 43	    } catch (err) {
 44	      console.error('Failed to refresh documents:', err);
 45	    }
 46	  }, []);
 47	
 48	  const refreshConversation = useCallback(async () => {
 49	    try {
 50	      setConversation(await window.knowledgeBase.conversation.get());
 51	      setHistoryError(null);
 52	    } catch (err) {
 53	      setHistoryError(formatIpcError(err));
 54	    }
 55	  }, []);
 56	
 57	  const refreshAll = useCallback(() => {
 58	    refreshDocuments();
 59	    refreshConversation();
 60	  }, [refreshDocuments, refreshConversation]);
 61	
 62	  useEffect(refreshAll, [refreshAll]);
 63	
 64	  const handleImport = useCallback(async () => {
 65	    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
 66	  }, []);
 67	
 68	  const handleAskQuestion = useCallback(async (question: string, followUpOf: string | null) => {
 69	    setFailed(null);
 70	    setPending({ question, followUpOf });
 71	    try {
 72	      await window.knowledgeBase.qa.ask(question, followUpOf ?? undefined);
 73	      await refreshConversation();
 74	    } catch (err) {
 75	      setFailed({ question, followUpOf, message: formatIpcError(err) });
 76	    } finally {
 77	      setPending(null);
 78	    }
 79	  }, [refreshConversation]);
 80	
 81	  const handleRetry = useCallback(() => {
 82	    if (failed) handleAskQuestion(failed.question, failed.followUpOf);
 83	  }, [failed, handleAskQuestion]);
 84	
 85	  const handleClearConversation = useCallback(async () => {
 86	    try {
 87	      await window.knowledgeBase.qa.clearHistory();
 88	      setFailed(null);
 89	      setSelection(null);
 90	    } catch (err) {
 91	      setHistoryError(formatIpcError(err));
 92	    }
 93	    await refreshConversation();
 94	  }, [refreshConversation]);
 95	
 96	  const documentIds = useMemo(() => new Set(documents.map(d => d.id)), [documents]);
 97	  const isDocumentAvailable = useCallback((id: string) => documentIds.has(id), [documentIds]);
 98	
 99	  const handleOpenDocument = useCallback((documentId: string) => {
100	    const doc = documents.find(d => d.id === documentId);
101	    if (doc) setSelectedDoc(doc);
102	  }, [documents]);
103	
104	  const handleSelectExchange = useCallback((exchangeId: string) => {
105	    setSelection(prev => ({ id: exchangeId, seq: (prev?.seq ?? 0) + 1 }));
106	  }, []);
107	
108	  return (
109	    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
110	      <header style={{
111	        padding: '12px 20px',
112	        background: '#16213e',
113	        borderBottom: '1px solid #0f3460',
114	        display: 'flex',
115	        alignItems: 'center',
116	        justifyContent: 'space-between',
117	      }}>
118	        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
119	        <button
120	          type="button"
121	          onClick={refreshAll}
122	          style={{
123	            padding: '6px 14px',
124	            background: '#0f3460',
125	            color: '#e0e0e0',
126	            border: '1px solid #1a1a4e',
127	            borderRadius: '4px',
128	            cursor: 'pointer',
129	            fontSize: '13px',
130	          }}
131	        >
132	          Refresh
133	        </button>
134	      </header>
135	
136	      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
137	        {/* Left panel: Document list + question history index */}
138	        <aside style={{
139	          width: '280px',
140	          borderRight: '1px solid #0f3460',
141	          display: 'flex',
142	          flexDirection: 'column',
143	          background: '#16213e',
144	        }}>
145	          <div style={{ display: 'flex', borderBottom: '1px solid #0f3460' }}>
146	            <button
147	              type="button"
148	              aria-pressed={activeTab === 'documents'}
149	              onClick={() => setActiveTab('documents')}
150	              style={tabStyle(activeTab === 'documents')}
151	            >
152	              Documents ({documents.length})
153	            </button>
154	            <button
155	              type="button"
156	              aria-pressed={activeTab === 'conversation'}
157	              onClick={() => setActiveTab('conversation')}
158	              style={tabStyle(activeTab === 'conversation')}
159	            >
160	              History ({conversation.length})
161	            </button>
162	          </div>
163	          {activeTab === 'documents' ? (
164	            <>
165	              <div style={{
166	                padding: '6px 16px',
167	                display: 'flex',
168	                justifyContent: 'flex-end',
169	              }}>
170	                <button
171	                  type="button"
172	                  onClick={handleImport}
173	                  style={{
174	                    padding: '4px 10px',
175	                    background: '#533483',
176	                    color: '#fff',
177	                    border: 'none',
178	                    borderRadius: '3px',
179	                    cursor: 'pointer',
180	                    fontSize: '12px',
181	                  }}
182	                >
183	                  + Import
184	                </button>
185	              </div>
186	              <DocumentList
187	                documents={documents}
188	                onSelect={setSelectedDoc}
189	                selectedId={selectedDoc?.id ?? null}
190	              />
191	            </>
192	          ) : (
193	            <ConversationHistory
194	              conversation={conversation}
195	              selectedId={selection?.id ?? null}
196	              onSelect={handleSelectExchange}
197	            />
198	          )}
199	        </aside>
200	
201	        {/* Right panel: optional document detail above the conversation */}
202	        <main style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
203	          {selectedDoc && (
204	            <section
205	              aria-label="Document detail"
206	              style={{ maxHeight: '45%', overflow: 'auto', padding: '16px 20px', borderBottom: '1px solid #0f3460', position: 'relative' }}
207	            >
208	              <button
209	                type="button"
210	                onClick={() => setSelectedDoc(null)}
211	                aria-label={`Close document ${selectedDoc.title}`}
212	                style={{
213	                  position: 'absolute',
214	                  top: '12px',
215	                  right: '16px',
216	                  padding: '3px 10px',
217	                  background: 'transparent',
218	                  color: '#c0c0e0',
219	                  border: '1px solid #2a3a6e',
220	                  borderRadius: '4px',
221	                  cursor: 'pointer',
222	                  fontSize: '12px',
223	                }}
224	              >
225	                Close
226	              </button>
227	              <DocumentDetail document={selectedDoc} />
228	            </section>
229	          )}
230	
231	          <QuestionPanel
232	            conversation={conversation}
233	            historyError={historyError}
234	            pending={pending}
235	            failed={failed}
236	            selection={selection}
237	            isDocumentAvailable={isDocumentAvailable}
238	            onAsk={handleAskQuestion}
239	            onRetry={handleRetry}
240	            onDismissError={() => setFailed(null)}
241	            onClear={handleClearConversation}
242	            onOpenDocument={handleOpenDocument}
243	            onSelectExchange={handleSelectExchange}
244	          />
245	        </main>
246	      </div>
247	
248	      <StatusBar status={appStatus} />
249	    </div>
250	  );
251	}
  1	import { useEffect, useMemo, useRef, useState, type CSSProperties, type FormEvent } from 'react';
  2	import { ConversationExchange } from '../../shared/types';
  3	import { ExchangeItem, metaText, smallButton, userBubble } from './ExchangeItem';
  4	
  5	export interface PendingQuestion {
  6	  question: string;
  7	  followUpOf: string | null;
  8	}
  9	
 10	export interface FailedQuestion extends PendingQuestion {
 11	  message: string;
 12	}
 13	
 14	/** A request to scroll to and highlight an exchange; `seq` lets the same exchange be selected twice. */
 15	export interface ExchangeSelection {
 16	  id: string;
 17	  seq: number;
 18	}
 19	
 20	interface Props {
 21	  conversation: ConversationExchange[];
 22	  historyError: string | null;
 23	  pending: PendingQuestion | null;
 24	  failed: FailedQuestion | null;
 25	  selection: ExchangeSelection | null;
 26	  isDocumentAvailable: (documentId: string) => boolean;
 27	  onAsk: (question: string, followUpOf: string | null) => void;
 28	  onRetry: () => void;
 29	  onDismissError: () => void;
 30	  onClear: () => Promise<void>;
 31	  onOpenDocument: (documentId: string) => void;
 32	  onSelectExchange: (exchangeId: string) => void;
 33	}
 34	
 35	export function QuestionPanel({
 36	  conversation,
 37	  historyError,
 38	  pending,
 39	  failed,
 40	  selection,
 41	  isDocumentAvailable,
 42	  onAsk,
 43	  onRetry,
 44	  onDismissError,
 45	  onClear,
 46	  onOpenDocument,
 47	  onSelectExchange,
 48	}: Props) {
